const p=location.pathname.split("/").pop();function toast(t){const e=document.createElement("div");e.className="toast";e.textContent=t;document.body.append(e);setTimeout(()=>e.remove(),2200)}function nav(a){return `<header class="nav"><a class="logo" href="../index.html"><i class="mark">B</i>bblbb</a><nav class="navlinks"><a class="${a==="discover"?"active":""}" href="discover.html">发现</a><a class="${a==="dashboard"?"active":""}" href="dashboard.html">我的工作台</a></nav><div class="navright"><a class="btn btn-ghost" href="login.html">登录</a><a class="btn btn-primary" href="dashboard.html">开始创作</a><i class="avatar">林</i></div></header><div class="noise"></div>`}function login(){document.body.innerHTML=nav("")+`<main class="auth-shell"><section class="auth-card"><div class="eyebrow">WELCOME BACK</div><h1 id="title">进入你的创作空间</h1><p id="desc">登录后继续编辑你的作品，或发现新的灵感。</p><div class="toggle"><button class="active" data-mode="login">登录</button><button data-mode="signup">注册</button></div><form id="form"><div class="field"><label>邮箱地址</label><input type="email" required></div><div class="field"><label>密码</label><input type="password" minlength="8" required></div><button class="btn btn-primary">继续 →</button></form><div class="auth-foot">继续即表示你同意服务条款与隐私政策</div></section></main>`;document.querySelectorAll("[data-mode]").forEach(b=>b.onclick=()=>{document.querySelectorAll("[data-mode]").forEach(x=>x.classList.remove("active"));b.classList.add("active");const s=b.dataset.mode==="signup";document.querySelector("#title").textContent=s?"创建你的创作空间":"进入你的创作空间";document.querySelector("#desc").textContent=s?"从一个空白画布开始，把想法变成作品。":"登录后继续编辑你的作品，或发现新的灵感。"});document.querySelector("#form").onsubmit=e=>{e.preventDefault();location.href="dashboard.html"}}function dashboard(){document.body.innerHTML=nav("dashboard")+`<main class="container"><div class="section-head"><div><div class="eyebrow">CREATOR OS / 工作台</div><h1>早上好，林晚。</h1><p class="muted">今天也把一个想法，变成可以被看见的作品。</p></div><button class="btn btn-green" id="new">＋ 新建项目</button></div><div class="dashboard"><section class="panel"><h3>本月作品表现</h3><div class="metric">18,642 <small>↗ 24.8%</small></div><p class="muted">总浏览量</p><div class="progress"><i></i></div></section><section class="panel"><h3>创作额度</h3><div class="metric">72 <small>/ 100</small></div><p class="muted">本月可用积分</p><button class="btn btn-ghost" style="width:100%;margin-top:18px" id="upgrade">升级计划 →</button></section><section class="panel"><h3>最近项目</h3><div class="mini-list"><a class="mini-item" href="work.html"><span class="mini-cover"></span><span><strong>星图导航页</strong><small>更新于 2 小时前</small></span><span class="status">已发布</span></a><a class="mini-item" href="work.html?title=节气日历插画集"><span class="mini-cover"></span><span><strong>节气日历插画集</strong><small>更新于昨天</small></span><span class="status">草稿</span></a></div></section><section class="panel"><h3>审核动态</h3><table class="table"><tr><th>作品</th><th>状态</th></tr><tr><td>星图导航页</td><td style="color:var(--green)">已通过</td></tr><tr><td>夏日限定主视觉</td><td style="color:var(--amber)">审核中</td></tr></table></section></div></main>`;document.querySelector("#new").onclick=()=>toast("新建项目流程即将打开");document.querySelector("#upgrade").onclick=()=>toast("计划选择已记录")}function discover(){document.body.innerHTML=nav("discover")+`<main class="container"><div class="section-head"><div><div class="eyebrow">OPEN GALLERY / 发现</div><h1>看见下一种<br><span style="color:var(--green)">可能性。</span></h1></div><p>这里聚集正在发生的创作。浏览灵感，也让你的作品被更多人看见。</p></div><div class="toolbar"><input class="search" id="q" placeholder="搜索作品、作者或关键词"><div class="chips"><button class="chip active">全部</button><button class="chip">页面</button><button class="chip">视觉</button><button class="chip">动画</button></div></div><div class="grid"><article class="work-card"><a href="work.html"><div class="cover"><span class="tag">页面</span><strong class="cover-title">星图导航页</strong></div><div class="card-body">林晚<div class="card-row">12.4k 浏览　♡ 892 喜欢</div></div></a></article><article class="work-card"><a href="work.html?title=像素农场小游戏"><div class="cover" style="background:linear-gradient(135deg,#7C3AED,#0EA5E9)"><span class="tag">页面</span><strong class="cover-title">像素农场小游戏</strong></div><div class="card-body">江晚明<div class="card-row">45.2k 浏览　♡ 2.3k 喜欢</div></div></a></article><article class="work-card"><a href="work.html?title=城市呼吸动态海报"><div class="cover" style="background:linear-gradient(135deg,#00E5A0,#7C3AED)"><span class="tag">动画</span><strong class="cover-title">城市呼吸·动态海报</strong></div><div class="card-body">陈屿<div class="card-row">8.1k 浏览　♡ 566 喜欢</div></div></a></article></div></main>`;document.querySelectorAll(".chip").forEach(b=>b.onclick=()=>{document.querySelectorAll(".chip").forEach(x=>x.classList.remove("active"));b.classList.add("active");toast("已切换分类："+b.textContent)})}function work(){const t=new URLSearchParams(location.search).get("title")||"星图导航页";document.body.innerHTML=nav("discover")+`<main class="container"><a href="discover.html" class="muted">← 返回发现</a><div class="profile-head"><span class="profile-avatar">林</span><div><h1>${t}</h1><p>林晚 · 产品设计师 · 2026.07.30 发布</p></div><button class="btn btn-primary" style="margin-left:auto" id="like">♡ 喜欢</button></div><div class="detail"><div class="detail-cover"><h1>${t}</h1></div><aside class="detail-copy"><div class="eyebrow">PROJECT NOTE</div><p>以星图为灵感的交互式导航页。用克制的动效和清晰的层级，让每一次探索都像在夜空中找到新的坐标。</p><div class="info-list"><div><span>浏览</span><b>12,402</b></div><div><span>喜欢</span><b id="likes">892</b></div><div><span>工具</span><b>Figma · Web</b></div><div><span>状态</span><b style="color:var(--green)">已发布</b></div></div><button class="btn btn-ghost" style="width:100%;margin-top:25px" id="share">↗ 分享作品</button></aside></div></main>`;document.querySelector("#like").onclick=()=>{document.querySelector("#likes").textContent="893";toast("已喜欢这件作品")};document.querySelector("#share").onclick=()=>toast("作品链接已复制")}if(p==="discover.html")discover();else if(p==="dashboard.html")dashboard();else if(p==="work.html")work();else login();
